{
    "path": "migrations/0001_studio_content.sql",
    "text": "CREATE TABLE studio_settings (id BIGSERIAL PRIMARY KEY, setting_key TEXT NOT NULL UNIQUE, setting_value JSONB NOT NULL DEFAULT '{}'::jsonb, updated_at TIMESTAMP NOT NULL DEFAULT now());\nCREATE TABLE studio_services (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', price_amount NUMERIC(12,2), price_note TEXT NOT NULL DEFAULT '', image_url TEXT NOT NULL DEFAULT '', is_published BOOLEAN NOT NULL DEFAULT false, sort_order INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now());\nCREATE TABLE studio_offers (id BIGSERIAL PRIMARY KEY, title TEXT NOT NULL, details TEXT NOT NULL DEFAULT '', starts_at DATE, ends_at DATE, is_published BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now());\nCREATE TABLE studio_bookings (id BIGSERIAL PRIMARY KEY, customer_name TEXT NOT NULL, phone TEXT NOT NULL, interest TEXT NOT NULL, preferred_date DATE, notes TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'new', created_at TIMESTAMP NOT NULL DEFAULT now());\nCREATE INDEX idx_studio_bookings_created ON studio_bookings(created_at DESC);\nCREATE TABLE studio_reviews (id BIGSERIAL PRIMARY KEY, customer_name TEXT NOT NULL, review_text TEXT NOT NULL, rating INTEGER, is_published BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMP NOT NULL DEFAULT now());\nCREATE TABLE studio_gallery (id BIGSERIAL PRIMARY KEY, title TEXT NOT NULL, image_url TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'Editorial inspiration', is_real_studio_work BOOLEAN NOT NULL DEFAULT false, is_published BOOLEAN NOT NULL DEFAULT false, sort_order INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT now());",
